  corners=np.array([[0,0],[1023,0],[0,1023],[1023,1023]],float);bs=corners@n;ts=corners@d
  for b in np.arange(bs.min()+gap/2,bs.max(),gap):
   t=np.arange(ts.min(),ts.max(),1.0);pts=b*n[None,:]+t[:,None]*d[None,:]
   valid=(pts[:,0]>=0)&(pts[:,0]<1024)&(pts[:,1]>=0)&(pts[:,1]<1024)
   p=pts[valid];tt=t[valid];ix=np.clip(np.rint(p[:,0]).astype(int),0,1023);iy=np.clip(np.rint(p[:,1]).astype(int),0,1023);labs=target[iy,ix]
   cuts=np.r_[0,np.flatnonzero(labs[1:]!=labs[:-1])+1,len(labs)]
   for aa,bb in zip(cuts[:-1],cuts[1:]):
    c=int(labs[aa]);run=bb-aa
    if c>=10 or run<minlen:continue
    nseg=int(math.ceil(run/maxlen));vals=np.linspace(tt[aa],tt[bb-1],nseg+1)
    for j in range(nseg):
     ta,tb=vals[j:j+2];p0=b*n+ta*d;p1=b*n+tb*d;vec=p1-p0;le=np.linalg.norm(vec)
